-- Afterwards run verify-0033.sql and expect all_migrations_ok = true.

begin;

-- ===========================================================================
-- 0033_public_evidence_snapshots.sql
-- ===========================================================================

-- HALO: stored snapshots of B12's public water data, written by the weekly
-- import (B19 plan, docs/backend/plans/b19-public-evidence-refresh.md).
--
-- Run once in the Supabase SQL editor. Safe to re-run. It needs nothing newer
-- than the baseline and reads no existing table, so it may be applied before
-- or after any of 0024 to 0032.
--
-- Locks: creates two new tables (the second with a foreign key to the first)
-- and one function. Nothing can be waiting on a new table, and no existing
-- table is touched, so no lock is taken on anything else.
--
-- ---------------------------------------------------------------------------
-- WHAT THIS IS FOR
-- ---------------------------------------------------------------------------
-- GET /api/water/notices (water.read) serves two public sources: the U.S.
-- Drought Monitor county statistics and the NC DEQ Division of Water
-- Resources conservation status table. Until now they were a copy bundled by
-- hand (lib/data/ncWaterStewardship.json). The weekly import
-- (GET /api/cron/public-evidence) fetches both, checks them strictly and keeps
-- a dated copy here only when the check passes:
--
--   public.public_evidence_snapshots   one row per stored copy of one source:
--                                      the source's own newest date, when HALO
--                                      fetched it, how many rows, the sha256 of
--                                      the exact bytes parsed, and the rows as
--                                      water.read serves them. The newest 8 per
--                                      source are kept; a failed fetch never
--                                      removes one.
--   public.public_evidence_runs        one row per source per run: stored or
--                                      failed, a fixed reason code, a row
--                                      count. No URL, body, value or error
--                                      text. The newest 200 per source are
--                                      kept.
--
-- PUBLIC DATA, NOT HOUSEHOLD DATA. Nothing here names a person or a home, so
-- there is no owner column and no foreign key to an account, and the privacy
-- export and clear do not touch these tables.
--
-- Degrades cleanly: until this is applied water.read serves the bundled copy
-- (and says so, with its retrieval date), the import answers a non-retryable
-- 503 feature_unavailable without fetching anything, and the operations
-- screen does not list these two sources.
--
-- Applying this turns nothing on: the import also needs
-- HALO_FEATURE_PUBLIC_IMPORT=on (YOUR_TODO.md 2.23).

create table if not exists public.public_evidence_snapshots (
  id             bigint      generated always as identity primary key,
  source         text        not null,
  source_date    date        not null,
  retrieved_at   timestamptz not null default now(),
  row_count      integer     not null,
  content_sha256 text        not null,
  body           jsonb       not null
);

create table if not exists public.public_evidence_runs (
  id          bigint      generated always as identity primary key,
  source      text        not null,
  ran_at      timestamptz not null default now(),
  outcome     text        not null,
  reason      text,
  row_count   integer,
  snapshot_id bigint      references public.public_evidence_snapshots (id) on delete set null
);

do $$
begin
  if not exists (select 1 from pg_constraint where conname = 'public_evidence_snapshots_source_check') then
    alter table public.public_evidence_snapshots add constraint public_evidence_snapshots_source_check
      check (source in ('usdm-drought', 'ncdwr-conservation'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'public_evidence_snapshots_date_check') then
    alter table public.public_evidence_snapshots add constraint public_evidence_snapshots_date_check
      check (source_date >= date '2000-01-01');
  end if;
  if not exists (select 1 from pg_constraint where conname = 'public_evidence_snapshots_rows_check') then
    alter table public.public_evidence_snapshots add constraint public_evidence_snapshots_rows_check
      check (row_count between 1 and 10000);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'public_evidence_snapshots_sha_check') then
    alter table public.public_evidence_snapshots add constraint public_evidence_snapshots_sha_check
      check (content_sha256 ~ '^[0-9a-f]{64}$');
  end if;
  -- A copy is one JSON object of at most about 4 MB (each source is under 1 MB).
  if not exists (select 1 from pg_constraint where conname = 'public_evidence_snapshots_body_check') then
    alter table public.public_evidence_snapshots add constraint public_evidence_snapshots_body_check
      check (jsonb_typeof(body) = 'object' and octet_length(body::text) <= 4000000);
  end if;
  if not exists (select 1 from pg_constraint where conname = 'public_evidence_runs_source_check') then
    alter table public.public_evidence_runs add constraint public_evidence_runs_source_check
      check (source in ('usdm-drought', 'ncdwr-conservation'));
  end if;
  -- A stored run has no reason; a failed one names a fixed code and nothing else.
  if not exists (select 1 from pg_constraint where conname = 'public_evidence_runs_outcome_check') then
    alter table public.public_evidence_runs add constraint public_evidence_runs_outcome_check
      check ((outcome = 'stored' and reason is null)
          or (outcome = 'failed' and reason is not null
              and reason ~ '^(timeout|network|too_large|invalid|no_timeout|bad_headers|shape|incomplete|bad_date|stale|internal|http_[0-9]{3})$'));
  end if;
  if not exists (select 1 from pg_constraint where conname = 'public_evidence_runs_rows_check') then
    alter table public.public_evidence_runs add constraint public_evidence_runs_rows_check
      check (row_count is null or row_count between 0 and 100000);
  end if;
end $$;

-- water.read and the operations screen read the newest row per source.
create index if not exists public_evidence_snapshots_newest
  on public.public_evidence_snapshots (source, id desc);
create index if not exists public_evidence_runs_newest
  on public.public_evidence_runs (source, id desc);

alter table public.public_evidence_snapshots enable row level security;
alter table public.public_evidence_runs      enable row level security;
-- No policies: service role only. The data is public, but only the import
-- may write it and only the server reads it, so a browser has no reason to
-- see the tables at all.
revoke all on table public.public_evidence_snapshots from anon, authenticated;
revoke all on table public.public_evidence_runs      from anon, authenticated;

-- ---------------------------------------------------------------------------
-- record_public_evidence_run: one run's results, in one transaction
-- ---------------------------------------------------------------------------
-- p_results: a JSON array of one entry per source, at most one each:
--   { "source": "usdm-drought", "outcome": "stored", "reason": null,
--     "row_count": 400,
--     "snapshot": { "source_date": "2026-10-13", "content_sha256": "...", "body": { ... } } }
--   { "source": "ncdwr-conservation", "outcome": "failed", "reason": "timeout",
--     "row_count": null }
-- A stored entry inserts its snapshot and a run row pointing at it; a failed
-- entry inserts only its run row, and may not carry a snapshot. Then the
-- source's copies beyond the newest 8, and its runs beyond the newest 200,
-- are removed: the newest copy is never among them, so a failed run can
-- never leave a source with fewer good copies than before. Concurrent runs
-- (an overlapping schedule) are taken one at a time.
create or replace function public.record_public_evidence_run(p_results jsonb)
returns jsonb
language plpgsql
security invoker
set search_path = public
as $$
declare
  item       jsonb;
  snap       jsonb;
  source_id  text;
  stored_id  bigint;
  recorded   jsonb := '[]'::jsonb;
begin
  if p_results is null or jsonb_typeof(p_results) <> 'array'
     or jsonb_array_length(p_results) not between 1 and 2 then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001',
      detail = 'p_results must be an array of one or two results';
  end if;
  if exists (select 1 from jsonb_array_elements(p_results) e where jsonb_typeof(e) <> 'object')
     or (select count(distinct e ->> 'source') from jsonb_array_elements(p_results) e) <> jsonb_array_length(p_results) then
    raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001',
      detail = 'each result is an object, and names a different source';
  end if;

  perform pg_advisory_xact_lock(hashtext('public.record_public_evidence_run'));

  for item in select e from jsonb_array_elements(p_results) e loop
    source_id := item ->> 'source';
    snap := item -> 'snapshot';
    stored_id := null;
    if item ->> 'outcome' = 'stored' then
      if snap is null or jsonb_typeof(snap) <> 'object' then
        raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001',
          detail = 'a stored result carries its snapshot';
      end if;
      insert into public.public_evidence_snapshots (source, source_date, row_count, content_sha256, body)
      values (source_id, (snap ->> 'source_date')::date, (item ->> 'row_count')::integer,
              snap ->> 'content_sha256', snap -> 'body')
      returning id into stored_id;
    elsif snap is not null and jsonb_typeof(snap) <> 'null' then
      raise exception 'HALO_INVALID_INPUT' using errcode = 'P0001',
        detail = 'a failed result stores no snapshot';
    end if;

    insert into public.public_evidence_runs (source, outcome, reason, row_count, snapshot_id)
    values (source_id, item ->> 'outcome', item ->> 'reason', (item ->> 'row_count')::integer, stored_id);

    delete from public.public_evidence_snapshots s
     where s.source = source_id
       and s.id not in (select k.id from public.public_evidence_snapshots k
                         where k.source = source_id order by k.id desc limit 8);
    delete from public.public_evidence_runs r
     where r.source = source_id
       and r.id not in (select k.id from public.public_evidence_runs k
                         where k.source = source_id order by k.id desc limit 200);

    recorded := recorded || jsonb_build_object('source', source_id, 'outcome', item ->> 'outcome', 'snapshotId', stored_id);
  end loop;
  return recorded;
end;
$$;

revoke execute on function public.record_public_evidence_run(jsonb) from public, anon, authenticated;
grant execute on function public.record_public_evidence_run(jsonb) to service_role;

